Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
RDMA/core: Fix double put of resource

Do not decrease the reference count of resource tracker object twice in
the error flow of res_get_common_doit.

Fixes: c5dfe0ea6ffa ("RDMA/nldev: Add resource tracker doit callback")
Link: https://lore.kernel.org/r/20200507062942.98305-1-leon@kernel.org
Signed-off-by: Maor Gottlieb <maorg@mellanox.com>
Signed-off-by: Leon Romanovsky <leonro@mellanox.com>
Signed-off-by: Jason Gunthorpe <jgg@mellanox.com>

Here is the root cause:
The bug was caused by the `rdma_restrack_put(res);` function being called twice in the error flow of the `res_get_common_doit` function, leading to a double decrement of the reference count for the resource tracker object. This improper management of the reference count could result in resource leaks or premature deallocation of the resource tracker object.

Here is the patch:

 static int res_get_common_doit(struct sk_buff *skb, struct nlmsghdr *nlh,
 			       struct netlink_ext_ack *extack,
 			       enum rdma_restrack_type res_type,
 			       res_fill_func_t fill_func)
 {
 	const struct nldev_fill_res_entry *fe = &fill_entries[res_type];
 	struct nlattr *tb[RDMA_NLDEV_ATTR_MAX];
 	struct rdma_restrack_entry *res;
 	struct ib_device *device;
 	u32 index, id, port = 0;
 	bool has_cap_net_admin;
 	struct sk_buff *msg;
 	int ret;

 	ret = nlmsg_parse_deprecated(nlh, 0, tb, RDMA_NLDEV_ATTR_MAX - 1,
 				     nldev_policy, extack);
 	if (ret || !tb[RDMA_NLDEV_ATTR_DEV_INDEX] || !fe->id || !tb[fe->id])
 		return -EINVAL;

 	index = nla_get_u32(tb[RDMA_NLDEV_ATTR_DEV_INDEX]);
 	device = ib_device_get_by_index(sock_net(skb->sk), index);
 	if (!device)
 		return -EINVAL;

 	if (tb[RDMA_NLDEV_ATTR_PORT_INDEX]) {
 		port = nla_get_u32(tb[RDMA_NLDEV_ATTR_PORT_INDEX]);
 		if (!rdma_is_port_valid(device, port)) {
 			ret = -EINVAL;
 			goto err;
 		}
 	}

 	if ((port && fe->flags & NLDEV_PER_DEV) ||
 	    (!port && ~fe->flags & NLDEV_PER_DEV)) {
 		ret = -EINVAL;
 		goto err;
 	}

 	id = nla_get_u32(tb[fe->id]);
 	res = rdma_restrack_get_byid(device, res_type, id);
 	if (IS_ERR(res)) {
 		ret = PTR_ERR(res);
 		goto err;
 	}

 	msg = nlmsg_new(NLMSG_DEFAULT_SIZE, GFP_KERNEL);
 	if (!msg) {
 		ret = -ENOMEM;
 		goto err_get;
 	}

 	nlh = nlmsg_put(msg, NETLINK_CB(skb).portid, nlh->nlmsg_seq,
 			RDMA_NL_GET_TYPE(RDMA_NL_NLDEV, fe->nldev_cmd),
 			0, 0);

 	if (fill_nldev_handle(msg, device)) {
 		ret = -EMSGSIZE;
 		goto err_free;
 	}

 	has_cap_net_admin = netlink_capable(skb, CAP_NET_ADMIN);

 	ret = fill_func(msg, has_cap_net_admin, res, port);
-
-	rdma_restrack_put(res);
 	if (ret)
 		goto err_free;

+	rdma_restrack_put(res);
 	nlmsg_end(msg, nlh);
 	ib_device_put(device);
 	return rdma_nl_unicast(sock_net(skb->sk), msg, NETLINK_CB(skb).portid);

 err_free:
 	nlmsg_free(msg);
 err_get:
 	rdma_restrack_put(res);
 err:
 	ib_device_put(device);
 	return ret;
 }



